inline std::vector<std::uint8_t> encrypted_pdf_bytes_from_hex(std::string_view hex) {
  const auto nibble = [](char value) -> int {
    if (value >= '0' && value <= '9') {
      return value - '0';
    }
    if (value >= 'a' && value <= 'f') {
      return value - 'a' + 10;
    }
    return -1;
  };
  std::vector<std::uint8_t> bytes;
  int high = -1;
  for (const char value : hex) {
    if (value == ' ' || value == '\r' || value == '\n' || value == '\t') {
      continue;
    }
    const int digit = nibble(value);
    if (digit < 0) {
      return {};
    }
    if (high < 0) {
      high = digit;
    } else {
      bytes.push_back(static_cast<std::uint8_t>((high << 4) | digit));
      high = -1;
    }
  }
  return high < 0 ? bytes : std::vector<std::uint8_t>{};
}

